          "expr": "datum._rowType === 'level3' ? true : datum._rowType === 'portfolio' ? !datum._parentL3Collapsed : datum._rowType === 'program' ? (!datum._parentL3Collapsed && !datum._parentPFCollapsed) : datum._rowType === 'plan' ? (!datum._parentL3Collapsed && !datum._parentPFCollapsed && !datum._parentPGCollapsed) : true"
